const T=DojoTraining,K=DojoKihon;
let selectedTrainingBelt=null;
function trainingOverview(){const rank=state.game.belt;return `<div class="training-overview"><div><span class="eyebrow">TREINO DA SUA FAIXA</span><h2>${G.BELTS[rank].name}</h2><p>Kihon e Ido geiko têm módulos separados, três fases cada e nota mínima crescente.</p></div><div class="training-shortcuts"><button class="outline" data-track="kihon">拳 &nbsp; Treinar Kihon</button><button class="outline" data-track="ido">➜ &nbsp; Treinar Ido geiko</button><button class="text-button" data-view="training">Ver todas as faixas →</button></div></div>`;}
function trainingPage(){const rank=selectedTrainingBelt??state.game.belt,available=rank<=state.game.belt,modules=T.modulesForBelt(rank),approved=Boolean(state.game.mastery?.[rank]);return `<section class="animate-in"><div class="eyebrow">DUAS TRILHAS · 13 GRADUAÇÕES ILUSTRATIVAS</div><h1>Kihon e Ido geiko por faixa</h1><p class="intro">26 módulos de treino e 78 fases, com dificuldade de 75% a 95%.</p><div class="training-select"><label>Faixa que você quer estudar<select id="training-belt">${G.BELTS.map((b,i)=>`<option value="${i}" ${i===rank?'selected':''}>${b.name}${i>state.game.belt?' · Prévia':''}</option>`).join('')}</select></label>${beltArt(rank,true)}</div><div class="learning-callout"><b>${T.complexity[rank]}</b><p>${available?`As atividades desta faixa estão disponíveis. A nota mínima é ${T.thresholds[rank]}%.`:'Você pode consultar o material. Os desafios são liberados quando sua graduação do app chegar a esta faixa.'}</p></div><div class="training-module-grid">${modules.map(m=>`<article class="training-module-card"><span class="module-glyph">${m.icon}</span><span class="difficulty-label">${m.type==='kihon'?'KIHON':'IDO GEIKO'} · ${m.pass}% PARA APROVAR</span><h2>${m.type==='kihon'?'Cuidar de cada fundamento':'Unir base, técnica e deslocamento'}</h2><p>${m.type==='kihon'?'Nome, altura, categoria, escuta e precisão dos fundamentos.':'Comandos, lados, combinações, memória e continuidade.'}</p><small>${m.phases.filter(p=>state.learning.phases[p.id]?.passed).length} / 3 fases aprovadas</small><button class="primary" data-module="${m.id}">Ver módulo <span>→</span></button></article>`).join('')}</div><div class="practical-gate"><span>🥋</span><div><h3>${approved?'Faixa com estudo e prática conferidos':'A subida pede conhecimento e prática'}</h3><p>${approved?'A conferência desta faixa foi registrada. A meta semanal de 200 XP pode liberar a próxima graduação.':'Para subir, reúna 200 XP na semana, aprove as seis fases de Kihon e Ido geiko da faixa atual e receba a conferência prática do sensei.'}</p><p>Com pelo menos 80 XP você protege a faixa enquanto trabalha na etapa. Abaixo de 80 XP, vale a regra de descida semanal. As faixas continuam válidas apenas no app.</p></div></div><div class="catalog-link"><button class="outline" data-view="kihon-audio">Ouvir o kihon por Te, Ashi, Shuto e Uke waza →</button></div><p class="week-note">Esta é uma trilha educativa do San Dojo digital. Ela não é um currículo oficial por kyu/dan e não substitui a avaliação ou a graduação real do dojo.</p></section>`;}
function trainingCheck(){if(!DojoAccounts.canManage())return "";const rank=state.game.belt,ready=T.ready(state.learning,rank),approval=state.learning.approvals['grade-'+rank];return `<div class="info-panel"><div class="eyebrow">CONFERÊNCIA DA GRADUAÇÃO ILUSTRATIVA</div><h2>Kihon e Ido geiko · ${G.BELTS[rank].name}</h2><p>O aluno precisa das seis fases aprovadas desta faixa. A conferência abaixo é registrada pela conta autenticada de administrador.</p><ul><li>Observar os fundamentos selecionados: base, altura, trajetória, controle e retorno.</li><li>Observar os deslocamentos e as combinações escolhidas pelo sensei.</li><li>Pedir que o aluno aplique uma correção e explique o que mudou.</li></ul>${approval?`<p class="approval-ok">✓ Conferência registrada.</p><p>${esc(approval.note)}</p>`:ready?`<label class="checkbox-label"><input id="training-observed" type="checkbox"> Observei Kihon, Ido geiko e as correções desta faixa.</label><label>Retorno ao aluno<input class="training-check-input" id="training-note" maxlength="300" placeholder="Um detalhe que melhorou e um ponto para continuar treinando"></label><button class="primary" data-approve-training="${rank}">Registrar a prática desta faixa →</button>`:'<p class="week-note">Aguardando aprovação nas três fases de Kihon e nas três fases de Ido geiko desta faixa.</p>'}</div>`;}
function kihonAudio(){return `<section class="animate-in"><div class="eyebrow">PRONÚNCIA · KIHON POR PARTE</div><h1>Ouça cada parte do kihon</h1><p class="intro">${K.terms.length} técnicas em quatro categorias, com áudio individual e sequência completa da categoria.</p><div class="learning-callout"><b>Seus vídeos também fazem parte do kihon.</b><p>O sensei pode adicionar um vídeo em cada técnica ou na categoria inteira. Entre com sua conta de administrador para usar a Biblioteca. Os alunos podem assistir aos materiais.</p></div><div class="kihon-category-nav">${K.groups.map(g=>`<a href="#kihon-audio" data-category-scroll="${g.id}">${g.name}<small>${g.terms.length} técnicas</small></a>`).join('')}</div>${K.groups.map(g=>`<section id="category-${g.id}" class="kihon-category"><div class="category-heading"><div><span lang="ja">${g.jp}</span><h2>${g.name}</h2><p>${g.desc}</p></div><div>${audioButtons(g.name)}<button class="outline" data-speak="Sequência · ${g.name}">Ouvir esta parte inteira ▶</button>${kihonMediaActions("kihon-parte-"+g.id,true)}</div></div><div class="kihon-audio-list">${g.terms.map((term,i)=>`<article><span class="kihon-item-number">${String(i+1).padStart(2,'0')}</span><div><h3>${term.name}</h3><p>${term.meaning}</p><small lang="ja">${term.say}</small></div><div class="kihon-item-actions">${audioButtons(term.name)}${kihonMediaActions(term.id)}</div></article>`).join('')}</div></section>`).join('')}<div class="info-panel"><h2>Referência do catálogo</h2><p>Lista de nomes baseada no kihon da Shinkyokushin Karate Schule IKKA/SSKA, adaptada para o San Dojo conforme a orientação do sensei. A ordem e as variações ensinadas no San Dojo seguem o sensei.</p><p>São áudios sintetizados para estudar os nomes. As descrições são apoios de vocabulário; a execução é praticada com orientação.</p><a href="${K.source}" target="_blank" rel="noopener">Consultar a referência de Shinkyokushin ↗</a></div></section>`;}
function weeklyMessage(){const xp=weekXP(),rank=state.game.belt,ready=Boolean(state.game.mastery?.[rank]);if(rank===12&&xp>=80)return 'Faixa protegida! Continue revisando os fundamentos e a prática.';if(xp>=200&&rank<12)return ready?'XP, fases e prática conferidos! A próxima faixa chega no fechamento da semana.':'XP atingidos e faixa protegida. Complete Kihon, Ido geiko e a conferência do sensei para subir.';if(xp>=80)return `Faixa protegida! Faltam ${200-xp} XP para a meta de subida, junto às fases e à conferência.`;return rank===0?'Comece com os módulos de Kihon e Ido geiko. A subida reúne 200 XP, fases aprovadas e prática conferida.':`Faltam ${80-xp} XP para proteger sua faixa nesta semana.`;}
const originalWeeklyWidget=weeklyWidget;
function weeklyTrainingWidget(){return originalWeeklyWidget().replace('<small class="app-only">','<button class="outline" style="margin-top:8px" data-view="training">Treinar Kihon e Ido geiko →</button><small class="app-only">');}
const originalBeltJourney=beltJourney;
function trainingBeltJourney(){return originalBeltJourney().replace('Sobe 1 faixa ao fechar a semana.','Pode subir 1 faixa com as fases e a prática conferidas.').replace('✦ Na zona de subida',state.game.mastery?.[state.game.belt]?'✦ Subida preparada':'✓ XP atingidos').replace('<div class="rules-strip">',trainingOverview()+'<div class="rules-strip">').replace("item.kind === 'starting' ? 'Primeiros passos' : 'Manteve a faixa'","item.kind === 'starting' ? 'Primeiros passos' : 'Manteve a faixa'");}
function weeklyRulesPanel(){return `<div class="info-panel"><h2>Como funcionam as faixas do aplicativo</h2><p>Para subir uma faixa na segunda-feira: pelo menos 200 XP na semana, seis fases aprovadas nos módulos de Kihon e Ido geiko da faixa atual e uma conferência prática registrada pelo sensei.</p><p>Com 80 a 199 XP, a faixa é mantida. Com 200 XP ou mais e a etapa prática ainda pendente, a faixa também fica protegida. Abaixo de 80 XP, desce uma etapa, sem passar da branca. No 1º dan ilustrativo, 80 XP mantêm a faixa.</p><p>A semana vai de segunda a domingo no horário de Brasília. Os XP semanais zeram; os totais, as aprovações e o histórico são preservados. Cada fase aprovada rende 20 XP uma vez por dia.</p><p>Os 26 módulos de Kihon e Ido geiko acompanham as 13 faixas do app, com notas mínimas de 75% a 95%. A trilha é educativa e não equivale ao currículo técnico de kyu/dan do San Dojo. O Premium não altera notas, liberações ou metas.</p><p><b>Faixas válidas apenas no app.</b> A graduação real é avaliada pelo sensei no dojo. Na versão conectada, os registros de conferência são exclusivos da conta de administrador. A observação da execução continua sendo feita na aula.</p></div>`;}

function kihonMediaActions(id,whole=false){const entry=state.media[id],has=entry&&(entry.youtubeId||entry.videoKey||entry.imageKey);if(!has&&!DojoAccounts.canManage())return '';return `<div class="kihon-material-actions">${has?`<button class="outline" data-kihon-material="${id}">Ver material ▶</button>`:''}${DojoAccounts.canManage()?`<button class="text-button" data-add-kihon-media="${id}">${has?'Editar material':whole?'Adicionar vídeo desta parte +':'Adicionar vídeo +'}</button>`:''}</div>`;}
let currentKihonMaterial="kihon-te-1";
function kihonMaterialPage(){const k=kihonMaterialById(currentKihonMaterial)||kihonMaterialById("kihon-te-1"),entry=state.media[k.id],has=entry&&(entry.youtubeId||entry.videoKey||entry.imageKey);return `<section class="animate-in"><button class="back-link" data-view="kihon-audio">← Voltar ao kihon</button><div class="eyebrow">KIHON · ${esc(k.group.name)}${k.whole?" · CATEGORIA INTEIRA":""}</div><h1>${esc(k.name)}</h1><p class="intro">${esc(k.meaning)}</p><p class="kata-large-reading" lang="ja">${k.say}</p>${audioButtons(k.name)}<div class="module-layout"><div class="info-panel"><h2>Sua demonstração no kihon</h2><p>Adicione seu vídeo, uma imagem de apoio e as orientações para estudar ${k.whole?"esta parte do kihon":"esta técnica"} com o sensei.</p>${DojoAccounts.canManage()?`<button class="primary" data-add-kihon-media="${k.id}">${has?"Editar meu material":"Adicionar meu vídeo"} →</button>`:!DojoAccounts.user?'<button class="outline" data-view="account">Entrar na área do sensei →</button>':''}<p class="week-note">Na versão conectada, os materiais ficam na biblioteca online. Somente o administrador pode alterá-los.</p></div><div class="module-material">${has?mediaMarkup(k.id):"<h2>Seu vídeo aparece aqui</h2><p>Este espaço está pronto para receber sua demonstração e imagem de apoio.</p>"}</div></div></section>`;}
